INSERT OR IGNORE INTO wiki_pages (id, mod_id, entity_type, entity_id, slug, page_type) VALUES ('seed:page:power:VulnerablePower', 'sts2', 'power', 'VulnerablePower', 'power:VulnerablePower', 'entity');
INSERT OR IGNORE INTO wiki_sections (id, page_id, section_key, content_type, sort_order) VALUES ('seed:section:power:VulnerablePower:document', 'seed:page:power:VulnerablePower', 'document', 'structured', 0);
INSERT OR IGNORE INTO wiki_revisions (id, section_id, revision_no, content, summary, source_type, source_reference) VALUES ('seed:revision:power:VulnerablePower:document:1', 'seed:section:power:VulnerablePower:document', 1, '{"kind":"power","page":{"title":"Vulnerable","stackType":"Duration","text":"Receive 50% more damage from Attacks for X turns.","order":["Additive effects such as StS2 Icon Strength.png Strength are applied before multiplicative effects like StS2 Icon Vulnerable.png Vulnerable. For example, if you have 2 StS2 Icon Strength.png Strength and play Strike on a StS2 Icon Vulnerable.png Vulnerable target, you will deal 12 damage ((6+2)×1.5) instead of 11 damage ((6×1.5)+2). Additive effects include StS2 Icon Strength.png Strength, StS2 Icon Vigor.png Vigor, Accuracy, StS2 StrikeDummy.png Strike Dummy and Enchantments such as Enchant Sharp.png Sharp, Enchant Vigorous.png Vigorous, and Enchant Momentum.png Momentum. Multiplicative effects are StS2 Icon Vulnerable.png Vulnerable, StS2 Icon Weak.png Weak, StS2 Icon DoubleDamage.png Double Damage, StS2 PenNib.png Pen Nib, StS2 Icon Flutter.png Flutter, StS2 Icon Shrink.png Shrink, StS2 Icon Soar.png Soar, StS2 Icon Slow.png Slow, and StS2 Icon Surrounded.png Surrounded.","Due to rounding, StS2 Icon Vulnerable.png Vulnerable deals 1 less damage for attacks with a base damage value not divisible by 2 (IE odd numbers). This damage reduction is magnified by multi-hit attacks. If StS2 PaperPhrog.png Paper Phrog or unupgraded Cruelty is in possession, then attacks'' divisibility by 4 is the deciding factor, rather than 2."],"effectsImmune":["Damaging Relics and Orbs do not interact with StS2 Icon Vulnerable.png Vulnerable.","Both StS2 Icon Poison.png Poison and StS2 Icon Doom.png Doom are not affected by StS2 Icon Vulnerable.png Vulnerable.","Only cards with the \"Attack\"-type can benefit from StS2 Icon Vulnerable.png Vulnerable. For example, Inferno, Serpent Form, Capture Spirit, and The Bomb are not affected by StS2 Icon Vulnerable.png Vulnerable.","Direct removal of HP does not count as damage, and thus is not affected by StS2 Icon Vulnerable.png Vulnerable. The secondary effects of the Attacks Hemokinesis and Strangle are not affected by StS2 Icon Vulnerable.png Vulnerable."]}}', 'Initial import from mod provided wiki data', 'mod_seed', 'src/lib/data/power-wiki.json#VulnerablePower');
UPDATE wiki_sections SET current_revision_id = 'seed:revision:power:VulnerablePower:document:1', version = 1 WHERE id = 'seed:section:power:VulnerablePower:document' AND current_revision_id IS NULL;
